\label{3.4-lm1}
Assume that ${\cal X}$ and ${\cal Y}$ are separable
Hilbert spaces.  For any $L\in
\Upsilon_p({\cal X};{\cal Y})$, there exist a sequence
$\{L_n\}_{n=1}^\infty\subset
L_{{\mathbb{F}}}^\infty\big(\Omega;L^p(0,T;{\cal L}({\cal X};{\cal Y}))\big)$
such that
 
\begin{equation}\label{3.4-lm1-eq1}
\lim_{n\to\infty} L_n v = Lv \quad \mbox{ in
}L_{{\mathbb{F}}}^2(\Omega;L^p(0,T;{\cal Y})),\quad \forall\, v\in
L^2_{{\mathbb{F}}}(\Omega;L^\infty(0,T;{\cal X})).
\end{equation}

\label{5.7-def1}
An operator $\Theta(\cdot)\in \Upsilon_2(H;U)$ is called an {\it optimal
feedback  operator} for Problem (SLQ) if
 
\begin{equation}\label{5.7-eq2}
\begin{array}{ll}\displaystyle {\cal J}(s,\eta;\Theta(\cdot)\bar x(\cdot))\leq
{\cal J}(s,\eta;u(\cdot)),\\[2mm]
\noalign{\smallskip} \displaystyle\qquad \forall\; (s,\eta)\in [0,T)\times
L^2_{{\cal F}_s}(\Omega;H),\;\; u(\cdot)\in
L^2_{\mathbb{F}}(s,T;U),
\end{array}
\end{equation}
 
where $\bar x(\cdot)=\bar x(\cdot\,;s,\eta, \Theta(\cdot)\bar x(\cdot))$ solves
the following equation:
 
\begin{equation}\label{5.2-eq1.1}
\left\{\begin{array}{ll}\displaystyle d\bar
x(t)=\big[(A+A_1)\bar x(t) + B\Theta \bar
x(t)\big]dt + \big(C \bar x(t)+D \Theta \bar
x(t)\big)dW(t) &\mbox{ in
}(s,T],\\
 
\noalign{\smallskip} \displaystyle \bar x(s)=\eta.
\end{array}
\right.
\end{equation}

\label{5.7-th1}
Let  {\bf (AS0)}-- {\bf (AS4)} hold. Then, Problem (SLQ) admits a
unique optimal feedback operator $\Theta(\cdot)\in \Upsilon_2(H;U)\cap
\Upsilon_2(H_\lambda;\widetilde U)$ if and only if the Riccati equation
\eqref{5.5-eq6} admits a unique transposition solution
$\big(P(\cdot),\Lambda(\cdot)\big)\in C_{{\mathbb{F}},w}\big([0,T];
L^{\infty}(\Omega;{\cal S}(H))\big) \times L^2_{{\mathbb{F}},D,w}(0,T; {\cal S}(H)) $
such that
 
\begin{equation}\label{5.7-eq5}
\begin{array}{ll}\displaystyle
K(\cdot)^{-1}\big[B(\cdot)^* P(\cdot)
+D(\cdot)^* P(\cdot)C(\cdot) +
D(\cdot)^*\Lambda(\cdot)\big]\in
\Upsilon_2(H;U)\cap \Upsilon_2(H_\lambda;\widetilde
U).
\end{array}
\end{equation}
 
In this case, the optimal feedback operator $\Theta(\cdot)$ is given by
 
\begin{equation}\label{5.10}
\begin{array}{ll}
 
\noalign{\smallskip} \displaystyle\Theta(\cdot)=-K(\cdot)^{-1}[B(\cdot)^* P(\cdot)
+D(\cdot)^* P(\cdot)C(\cdot) + D(\cdot)^*\Lambda(\cdot)].
\end{array}
\end{equation}
 
Furthermore,
 
\begin{equation}\label{Value}
\inf_{u\in
L^2_{\mathbb{F}}(s,T;U)}{\cal J}(s,\eta;u)=\frac{1}{2}\,{\mathbb{E}}\langle
P(s)\eta,\eta\rangle_H.
\end{equation}

\label{lm11-1}
The  set
 
$$
\begin{array}{ll}\displaystyle
\big\{\tilde x_2(\cdot)\;\big|\; \tilde x_2(\cdot)\mbox{ solves }
\eqref{op-fsystem4} \mbox{ with }t=0,\;\tilde \xi_2=0,\; \tilde
v_2=0 \mbox{ and }\tilde u_2\in L^4_{{\mathbb{F}}}(\Omega;L^2(0,T;H)) \big\}
\end{array}
$$
 
is dense in $L^2_{{\mathbb{F}}}(0,T;H)$.

\label{lemma2.1}\cite[Lemma 2.5]{Lu-Zhang-book}
 
Assume that $p\in(1,\infty]$, $q=\left\{\begin{array}{ll}\frac{p}{p-1}&\hbox{if
}\ p\in (1,\infty),\\[2mm] 1&\hbox{if }\ p=\infty,\end{array}\right.$ $f_1\in
L^p_{{\mathbb{F}}}(0,T;$ $L^2(\Omega;H))$ and $f_2\in
L^q_{{\mathbb{F}}}(0,T;L^2(\Omega;H))$. Then there exists a monotonic sequence
$\{h_n\}_{n=1}^\infty$ of positive numbers such that
$\displaystyle\lim_{n\to\infty}h_n=0$, and
 
\begin{equation}\label{2.21}
\lim_{n\to\infty}\frac{1}{h_n}\int_t^{t+h_n}\mathbb{E} \langle
f_1(t),f_2(\tau)\rangle_{H} d\tau=\mathbb{E} \langle
f_1(t),f_2(t)\rangle_{H},\qquad\hbox{\rm a.e.{ }}\, t\in
 [0,T].
 \end{equation}

\label{th1}
Let ({\bf AS0})--({\bf AS4}) hold and $\Theta\in \Upsilon_2(H;U)\cap
\Upsilon_2(H_\lambda;\widetilde U)$, and $(\overline P,\overline\Lambda)$ be the
$H_\lambda$-transposition solution of (\ref{Relaxed-t-solution-Riccati})
corresponding to $\Theta$. Let
 
\begin{equation}\label{th1-eq1}
\overline K=R+D^{*}\overline PD,\ \ \overline L=D^{*} \overline P C
+B^*\overline P +D^*\overline\Lambda.
\end{equation}
 
Then $\Theta$ is an optimal feedback
operator for Problem (SLQ) if and only if
 
\begin{equation}\label{Nece-1}
\overline K(t,\omega)\geq0, \mbox{ for a.e. }(t,\omega)\in (0,T)\times\Omega,
\end{equation}
 
 
\begin{equation}\label{Nece-3}
\overline L \in  \Upsilon_2(H;U)\cap \Upsilon_2(H_\lambda;\widetilde U),
\end{equation}
 
and
 
\begin{equation}\label{Nece-2}
\overline K(t,\omega)\Theta(t,\omega)+\overline L(t,\omega)=0 \quad\mbox{ in
}\;{\cal L}(H;U) \mbox{ for a.e. }(t,\omega)\in (0,T)\times\Omega.
\end{equation}

\label{Lebesgue-differential-theorem}
Suppose $Y(\cdot)\in L^2_{{\mathbb{F}}}(0,T; H)$ is a
given process satisfying that for a.e. $t\in
[0,T]$, there is a sequence of decreasing
positive numbers $\{\varepsilon_n\}_{n=1}^\infty$ such
that
 
\begin{equation}\label{3.4-eq16}
\begin{array}{ll}
 
\noalign{\smallskip} \displaystyle \lim_{\varepsilon_n\to 0}
\int_t^{t+\varepsilon_n}\frac{{\mathbb{E}}_t Y(r)}{\varepsilon_n}dr=0
\mbox{ in }H,\ \ \quad{\mathbb{P}}\mbox{-a.s.}
 
\end{array}
\end{equation}
 
Then we have $Y=0$, for a.e.
$(t,\omega)\in[0,T)\times\Omega$.

\cite[Lemma 3.9]{Lu-Zhang-arxiv-2019}\label{lm11}
The set
 
$$
\begin{array}{ll}\displaystyle
\big\{x_2(\cdot)\;\big|\; x_2(\cdot)\mbox{ solves }
\eqref{op-fsystem2}
\mbox{ with }t=0,\; \xi_2=0,\;  v_2=0\mbox{ and } u_2\in
L^4_{{\mathbb{F}}}(\Omega;L^2(0,T;H)) \big\}
\end{array}
$$
 
is dense in $L^2_{{\mathbb{F}}}(0,T;H)$.
